return "#获取基础信息\nget_invite_info 32001 {\n    response {\n        .friend_brief {\n            playerid 1 : integer\n            name 2 : string #昵称\n            head_sculpture 3 : string #玩家头像\n            level 4 : integer #等级\n            class 5 : integer #学籍\n            fightpower 6 : integer #战力\n            lastlogin 7 : string # 最后离线时间 -1 表示在线\n            gift 8 : integer #已送出 已收到 已领取 分别对应第0-2三位\n        }\n\n        result 0 : integer\n        invitenum 1 : integer # 已邀请玩家数\n        isoldplayer  2 : integer # 0 新玩家 1 老玩家\n        binduid  3 : integer # 绑定的uid\n        inviteplayer 4 : *friend_brief #邀请玩家列表\n    }\n}\n#绑定邀请码\ninvite_binduid 32002 {\n    request {\n        binduid 0 : integer # 绑定的uid\n    }\n    response {\n        result 0 : integer# 1 sucess 2 已经绑定邀请码 3 邀请码绑定到达上限 4 邀请码无效 5 等级已超过绑定限制 6 只能绑定同服玩家\n    }\n}\n\n#解除邀请绑定\nterminate_binduid 32003 {\n    request {\n        binduid 0 : integer\n    }\n    response {\n        result 0 : integer # 1 success\n    }\n}\n#查询邀请任务\nget_invite_task_info 32004 {\n    request {\n        type 0 : integer #任务类型：1 受邀任务， 2邀请任务， 3 召回任务\n    }\n    response {\n        .task {\n            taskid 0 : integer  #任务id\n            percent 1 : integer    #完成百分比\n            need 2 : integer #需求量\n            finished 3 : integer #完成量\n            status 4 : integer # 1进行中 2 未领取 3 已完成\n        }\n        result 0 : integer\n        list 1 : *task\n        type 2 : integer\n    }\n}\n\n#领取邀请任务奖励\nget_invite_task_reward 32005 {\n    request {\n        taskid 0 : integer \n    }\n    response {\n        result 0 : integer\n        gold 1 : integer\n        diamond 2 : integer\n        items 3 : *item\n    }\n}\n\n#查询召回绑定信息\nget_recall_bind_info 32006 {\n    response {\n        result 0 : integer\n        binduid 1 : integer\n    }\n}\n\n#绑定召回码\nbind_recall_code 32007 {\n    request {\n        binduid 0 : integer\n    }\n    response {\n        result 0 : integer # 1 成功 2 已经绑定召回码 3 回归玩家才可以绑定召回码 4 召回码错误\n        gold 1 : integer\n        diamond 2 : integer\n        items 3 : *item\n    }\n}\n\n"
